create table if not exists public.quote_number_sequences (user_id uuid primary key references auth.users(id) on delete cascade, last_year integer not null, last_value integer not null default 0);
create table if not exists public.quotes (id uuid primary key default gen_random_uuid(), user_id uuid not null references auth.users(id) on delete cascade, customer_id uuid not null references public.customers(id) on delete restrict, quote_number text not null, title text not null check (length(trim(title)) > 0), quote_date date not null, valid_until date not null check (valid_until >= quote_date), description text not null default '', status text not null default 'Concept' check (status in ('Concept','Verzonden','Geaccepteerd','Afgewezen')), remarks text not null default '', payment_term_days integer not null check (payment_term_days > 0), terms text not null default '', created_at timestamptz not null default now(), updated_at timestamptz not null default now(), unique (user_id, quote_number));
create table if not exists public.quote_items (id uuid primary key default gen_random_uuid(), quote_id uuid not null references public.quotes(id) on delete cascade, position integer not null check (position >= 0), description text not null default '', quantity numeric(12,3) not null check (quantity > 0), unit text not null check (unit in ('uur','stuk','m²','meter','dag','vast bedrag')), unit_price integer not null check (unit_price >= 0), vat_percentage integer not null check (vat_percentage in (0,9,21)), created_at timestamptz not null default now(), updated_at timestamptz not null default now(), unique (quote_id, position));
create index if not exists quotes_user_id_idx on public.quotes(user_id); create index if not exists quotes_customer_id_idx on public.quotes(customer_id); create index if not exists quotes_created_at_idx on public.quotes(created_at desc); create index if not exists quote_items_quote_id_idx on public.quote_items(quote_id);
create or replace function public.set_updated_at() returns trigger language plpgsql as $$ begin new.updated_at=now(); return new; end; $$;
drop trigger if exists quotes_set_updated_at on public.quotes; create trigger quotes_set_updated_at before update on public.quotes for each row execute function public.set_updated_at();
drop trigger if exists quote_items_set_updated_at on public.quote_items; create trigger quote_items_set_updated_at before update on public.quote_items for each row execute function public.set_updated_at();
alter table public.quotes enable row level security; alter table public.quote_items enable row level security; alter table public.quote_number_sequences enable row level security;
revoke all on table public.quote_number_sequences from public, anon, authenticated;
drop policy if exists "quotes_select" on public.quotes; create policy "quotes_select" on public.quotes for select using ((select auth.uid())=user_id);
drop policy if exists "quotes_insert" on public.quotes; create policy "quotes_insert" on public.quotes for insert with check ((select auth.uid()) is not null and (select auth.uid())=user_id and exists(select 1 from public.customers c where c.id=customer_id and c.user_id=(select auth.uid())));
drop policy if exists "quotes_update" on public.quotes; create policy "quotes_update" on public.quotes for update using ((select auth.uid())=user_id) with check ((select auth.uid()) is not null and (select auth.uid())=user_id and exists(select 1 from public.customers c where c.id=customer_id and c.user_id=(select auth.uid())));
drop policy if exists "quotes_delete" on public.quotes; create policy "quotes_delete" on public.quotes for delete using ((select auth.uid())=user_id);
drop policy if exists "quote_items_select" on public.quote_items; create policy "quote_items_select" on public.quote_items for select using (exists(select 1 from public.quotes q where q.id=quote_id and q.user_id=(select auth.uid())));
drop policy if exists "quote_items_insert" on public.quote_items; create policy "quote_items_insert" on public.quote_items for insert with check (exists(select 1 from public.quotes q where q.id=quote_id and q.user_id=(select auth.uid())));
drop policy if exists "quote_items_update" on public.quote_items; create policy "quote_items_update" on public.quote_items for update using (exists(select 1 from public.quotes q where q.id=quote_id and q.user_id=(select auth.uid()))) with check (exists(select 1 from public.quotes q where q.id=quote_id and q.user_id=(select auth.uid())));
drop policy if exists "quote_items_delete" on public.quote_items; create policy "quote_items_delete" on public.quote_items for delete using (exists(select 1 from public.quotes q where q.id=quote_id and q.user_id=(select auth.uid())));
create or replace function public.next_quote_number() returns text language plpgsql security definer set search_path='' as $$ declare current_user_id uuid:=auth.uid(); current_year integer:=extract(year from current_date); next_value integer; begin if current_user_id is null then raise exception 'Niet ingelogd'; end if; insert into public.quote_number_sequences(user_id,last_year,last_value) values(current_user_id,current_year,1) on conflict(user_id) do update set last_value=case when public.quote_number_sequences.last_year=excluded.last_year then public.quote_number_sequences.last_value+1 else 1 end,last_year=excluded.last_year returning last_value into next_value; return format('OFF-%s-%s',current_year,lpad(next_value::text,4,'0')); end; $$;
create or replace function public.validate_quote_payload(payload jsonb) returns void language plpgsql security invoker set search_path='' as $$ declare item jsonb; positions integer[]; begin if jsonb_typeof(payload) is distinct from 'object' then raise exception 'Ongeldig offerte-payload'; end if; if coalesce(payload->>'customerId','') !~* '^[0-9a-f]{8}-[0-9a-f]{4}-[1-5][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$' then raise exception 'Ongeldige klant-id'; end if; if trim(coalesce(payload->>'title',''))='' then raise exception 'Titel is verplicht'; end if; if coalesce(payload->>'date','')='' or coalesce(payload->>'validUntil','')='' then raise exception 'Datum en geldig-tot zijn verplicht'; end if; if (payload->>'validUntil')::date < (payload->>'date')::date then raise exception 'Geldig-tot mag niet vóór de offertedatum liggen'; end if; if coalesce((payload->>'paymentTermDays')::integer,0)<=0 then raise exception 'Betalingstermijn moet groter dan nul zijn'; end if; if coalesce(payload->>'status','') not in ('Concept','Verzonden','Geaccepteerd','Afgewezen') then raise exception 'Ongeldige offertestatus'; end if; if jsonb_typeof(payload->'items') is distinct from 'array' then raise exception 'Offertregels moeten een array zijn'; end if; if jsonb_array_length(payload->'items') = 0 then raise exception 'Een offerte moet minimaal één regel hebben'; end if; select array_agg((value->>'position')::integer) into positions from jsonb_array_elements(payload->'items'); if array_length(positions,1)<>array_length(array(select distinct unnest(positions)),1) then raise exception 'Regelposities moeten uniek zijn'; end if; for item in select value from jsonb_array_elements(payload->'items') loop if coalesce((item->>'position')::integer,-1)<0 then raise exception 'Regelpositie is ongeldig'; end if; if coalesce((item->>'quantity')::numeric,0)<=0 then raise exception 'Aantal moet groter dan nul zijn'; end if; if coalesce((item->>'pricePerUnitCents')::integer,-1)<0 then raise exception 'Eenheidsprijs mag niet negatief zijn'; end if; if coalesce(item->>'unit','') not in ('uur','stuk','m²','meter','dag','vast bedrag') then raise exception 'Ongeldige eenheid'; end if; if coalesce((item->>'vatRate')::integer,-1) not in (0,9,21) then raise exception 'Ongeldig btw-percentage'; end if; end loop; end; $$;
create or replace function public.create_quote(payload jsonb) returns uuid language plpgsql security invoker set search_path='' as $$ declare uid uuid:=auth.uid(); qid uuid; item jsonb; quote_number text; customer uuid; begin if uid is null then raise exception 'Niet ingelogd'; end if; perform public.validate_quote_payload(payload); customer:=(payload->>'customerId')::uuid; if not exists(select 1 from public.customers c where c.id=customer and c.user_id=uid) then raise exception 'Customer not found or access denied'; end if; quote_number:=public.next_quote_number(); insert into public.quotes(user_id,customer_id,quote_number,title,quote_date,valid_until,description,status,remarks,payment_term_days,terms) values(uid,customer,quote_number,trim(payload->>'title'),(payload->>'date')::date,(payload->>'validUntil')::date,coalesce(payload->>'description',''),payload->>'status',coalesce(payload->>'remarks',''),(payload->>'paymentTermDays')::integer,coalesce(payload->>'terms','')) returning id into qid; for item in select value from jsonb_array_elements(payload->'items') loop insert into public.quote_items(quote_id,position,description,quantity,unit,unit_price,vat_percentage) values(qid,(item->>'position')::integer,coalesce(item->>'description',''),(item->>'quantity')::numeric,item->>'unit',(item->>'pricePerUnitCents')::integer,(item->>'vatRate')::integer); end loop; if not exists(select 1 from public.quote_items qi where qi.quote_id=qid) then raise exception 'Een offerte moet minimaal één regel hebben'; end if; return qid; end; $$;
create or replace function public.update_quote(p_quote_id uuid,payload jsonb) returns void language plpgsql security invoker set search_path='' as $$ declare uid uuid:=auth.uid(); item jsonb; customer uuid; begin if uid is null then raise exception 'Niet ingelogd'; end if; perform public.validate_quote_payload(payload); if not exists(select 1 from public.quotes q where q.id=p_quote_id and q.user_id=uid) then raise exception 'Offerte niet gevonden of toegang geweigerd'; end if; customer:=(payload->>'customerId')::uuid; if not exists(select 1 from public.customers c where c.id=customer and c.user_id=uid) then raise exception 'Customer not found or access denied'; end if; update public.quotes set customer_id=customer,title=trim(payload->>'title'),quote_date=(payload->>'date')::date,valid_until=(payload->>'validUntil')::date,description=coalesce(payload->>'description',''),status=payload->>'status',remarks=coalesce(payload->>'remarks',''),payment_term_days=(payload->>'paymentTermDays')::integer,terms=coalesce(payload->>'terms','') where id=p_quote_id and user_id=uid; delete from public.quote_items where quote_id=p_quote_id; for item in select value from jsonb_array_elements(payload->'items') loop insert into public.quote_items(quote_id,position,description,quantity,unit,unit_price,vat_percentage) values(p_quote_id,(item->>'position')::integer,coalesce(item->>'description',''),(item->>'quantity')::numeric,item->>'unit',(item->>'pricePerUnitCents')::integer,(item->>'vatRate')::integer); end loop; if not exists(select 1 from public.quote_items qi where qi.quote_id=p_quote_id) then raise exception 'Een offerte moet minimaal één regel hebben'; end if; end; $$;
revoke all on function public.next_quote_number() from public, anon, authenticated; revoke all on function public.validate_quote_payload(jsonb) from public, anon, authenticated; revoke all on function public.create_quote(jsonb) from public, anon, authenticated; revoke all on function public.update_quote(uuid,jsonb) from public, anon, authenticated;
grant execute on function public.next_quote_number() to authenticated; grant execute on function public.validate_quote_payload(jsonb) to authenticated; grant execute on function public.create_quote(jsonb) to authenticated; grant execute on function public.update_quote(uuid,jsonb) to authenticated;
